      result.push_back(false);
      continue;
    }

    if (voucher.description.empty()) {
      result.push_back(false);
      continue;
    }

    if (voucher.claims.empty()) {
      result.push_back(false);
      continue;
    }

    result.push_back(true);
  }

  return result;
  }

