struct ClickEvent {
  vector<string> options;
  int index;

  ClickEvent(const vector<string> &options, int &index) : options(options), index(index){}

  void detect_click() {
    if (options.empty()) return;
    int n = options.size();
    for (int i = 0; i < n; ++i) {
      if (ce.element == options[i]) {
        index = i;
        break;
      }
    }
    if (index != 0) {
      options.push_back(ce.element);
      return;
    }
    return;
  }

}

